// ── SSL Pinning with Dio ────────────────────────────
Dio buildSecureDio() {
  final dio = Dio();
  final adapter = dio.httpClientAdapter as IOHttpClientAdapter;
  // Runs AFTER the OS has validated the chain — the right hook for a pin.
  // badCertificateCallback is the classic mistake: it fires only when
  // validation already failed, so a proxy CA installed in the trust store
  // never reaches it and the pin is silently bypassed.
  adapter.validateCertificate = (cert, host, port) {
    if (cert == null) return false;
    final fingerprint = sha256.convert(cert.der).toString();
    return fingerprint == kExpectedFingerprint; // false = reject
  };
  return dio;
}

