Future<Dio> createPinnedDio() async {
  final pem = await rootBundle.load('assets/certs/api_example_com.pem');
  final ctx = SecurityContext(withTrustedRoots: false)
    ..setTrustedCertificatesBytes(pem.buffer.asUint8List());

  final dio = Dio(BaseOptions(baseUrl: 'https://api.example.com'));
  (dio.httpClientAdapter as IOHttpClientAdapter).createHttpClient =
      () => HttpClient(context: ctx);   // every other chain fails the handshake
  return dio;
