/// Thin channel over Play Integrity / App Attest — the native side returns an
/// opaque token; Dart deliberately cannot read or judge it.
class Attestation {
  static const _channel = MethodChannel('app/attestation');

  Future<String> tokenFor(String serverNonce) async {
    final token = await _channel.invokeMethod<String>('attest', {'nonce': serverNonce});
    return token!;
  }
}

class AttestationInterceptor extends Interceptor {
  AttestationInterceptor(this._api, this._attestation);
  final Dio _api;
  final Attestation _attestation;

  @override
  Future<void> onRequest(RequestOptions options, RequestInterceptorHandler h) async {
    if (options.extra['attest'] == true) {
      // The nonce comes from the server, so a captured token cannot be replayed
      final nonce = (await _api.post('/v1/attest/nonce')).data['nonce'] as String;
      options.headers['X-Integrity-Token'] = await _attestation.tokenFor(nonce);
    }
    h.next(options);
  }
}

