final _aead = AesGcm.with256bits();
const _storage = FlutterSecureStorage();
final _rng = Random.secure();

/// One random data key, wrapped by the platform keystore. Rotating the cache
/// means replacing this value, not rewriting every file.
Future<SecretKey> _dataKey() async {
  final stored = await _storage.read(key: 'cache_key');
  if (stored != null) return SecretKey(base64Decode(stored));
  final key = await _aead.newSecretKey();
  await _storage.write(key: 'cache_key', value: base64Encode(await key.extractBytes()));
  return key;
}

Future<Uint8List> sealDocument(List<int> plaintext) async {
  final nonce = List<int>.generate(12, (_) => _rng.nextInt(256)); // fresh every message
  final box = await _aead.encrypt(plaintext, secretKey: await _dataKey(), nonce: nonce);
  return Uint8List.fromList(box.concatenation()); // nonce + ciphertext + MAC
}

Future<List<int>> openDocument(Uint8List sealed) async {
  final box = SecretBox.fromConcatenation(sealed, nonceLength: 12, macLength: 16);
  // Throws SecretBoxAuthenticationError on a tampered file — parse nothing before this
  return _aead.decrypt(box, secretKey: await _dataKey());
}

