      for (final purchase in updates) {
        if (purchase.status == PurchaseStatus.pending) continue;

        // ❌ if (purchase.status == PurchaseStatus.purchased) unlockPremium();
        // The status is a claim from a process the attacker controls.

        if (purchase.status == PurchaseStatus.purchased ||
            purchase.status == PurchaseStatus.restored) {
          // ✅ The store's signed receipt goes to our server, which verifies it
          // with Apple/Google and binds the transaction to this account.
          final res = await _api.post('/v1/purchases/verify', data: {
            'source': purchase.verificationData.source,
            'receipt': purchase.verificationData.serverVerificationData,
            'productId': purchase.productID,
          });
          _entitlements.applyServerTruth(res.data); // short TTL, server-signed
        }

        // Acknowledge only after the server has recorded it: an Android purchase
        // left pending for three days is refunded automatically.
        if (purchase.pendingCompletePurchase) {
          await _iap.completePurchase(purchase);
        }
      }
    });
  }

  Future<void> buy(ProductDetails product, String userId) =>
      _iap.buyNonConsumable(
        purchaseParam: PurchaseParam(
          productDetails: product,
          applicationUserName: userId, // ties the receipt to one account
        ),
      );
}
